	/**  "Renamed 12 titles". */
	summary: string,
	/**  The muted line under it; sizes are in `bytes`. */
	detail: string,
	bytes: number | null,
	/**  The journal batch of a rename or move. */
	batch_id: string | null,
	/**  When the entry was wholly undone (epoch milliseconds). */
